public with sharing class EmployeeDirectoryService {
    public static List<FB_Employee__c> getDirectory() {
        Schema.DescribeSObjectResult objectDescribe = Schema.sObjectType.FB_Employee__c;
        if (objectDescribe == null || !objectDescribe.isViewable()) {
            return new List<FB_Employee__c>();
        }

        Map<String, Schema.DescribeFieldResult> fieldMap = objectDescribe.fields.getMap();

        if (!isFieldReadable(fieldMap, 'Id') || !isFieldReadable(fieldMap, 'Name')) {
            return new List<FB_Employee__c>();
        }

        List<String> selectedFields = new List<String>{ 'Id', 'Name' };

        if (isFieldReadable(fieldMap, 'Department__c')) {
            selectedFields.add('Department__c');
        }
        if (isFieldReadable(fieldMap, 'Salary__c')) {
            selectedFields.add('Salary__c');
        }
        if (isFieldReadable(fieldMap, 'Personal_Email__c')) {
            selectedFields.add('Personal_Email__c');
        }

        String query = 'SELECT ' + String.join(selectedFields, ', ') + ' FROM FB_Employee__c ORDER BY Name ASC';
        return (List<FB_Employee__c>) Database.query(query);
    }

    private static Boolean isFieldReadable(Map<String, Schema.DescribeFieldResult> fieldMap, String fieldName) {
        Schema.DescribeFieldResult fieldDescribe = fieldMap.get(fieldName);
        return fieldDescribe != null && fieldDescribe.isAccessible();
    }
}
